<script setup lang="ts">
import { computed, ref } from "vue";
import { LifeBuoy, Search, MessageCircle, ChevronDown, CheckCircle2 } from "lucide-vue-next";
import SiteHeader from "../components/SiteHeader.vue";
import SiteFooter from "../components/SiteFooter.vue";

interface Ticket { id: string; topic: string; message: string; createdAt: string; status: string }
const query = ref("");
const topic = ref("Order and delivery");
const message = ref("");
const submitted = ref(false);
const faqs = [
  { q: "How can I track my order?", a: "Open My Account → My orders, then choose Track order to see the latest delivery step." },
  { q: "How do I request a return?", a: "Open Returns & refunds, select the order and item, then send the reason to start a request." },
  { q: "Which payment methods are available?", a: "This demo supports cash on delivery and a simulated card payment. No real payment is taken." },
  { q: "How do I contact a seller?", a: "Open Buyer–Seller chat and choose a store to start a conversation." },
];
const filteredFaqs = computed(() => faqs.filter((item) => `${item.q} ${item.a}`.toLowerCase().includes(query.value.toLowerCase())));
const tickets = ref<Ticket[]>(JSON.parse(localStorage.getItem("bx-support-tickets") ?? "[]") as Ticket[]);
function submit() { if (!message.value.trim()) return; tickets.value.unshift({ id: `BX-${Date.now().toString().slice(-6)}`, topic: topic.value, message: message.value.trim(), createdAt: new Date().toISOString(), status: "Open" }); localStorage.setItem("bx-support-tickets", JSON.stringify(tickets.value)); message.value = ""; submitted.value = true; }
</script>

<template><div class="page-shell"><SiteHeader /><main class="container content-page"><div class="breadcrumb"><RouterLink to="/">Home</RouterLink><span>/</span><span>Support center</span></div><div class="support-intro"><span class="support-mark"><LifeBuoy /></span><span class="eyebrow">WE’RE HERE TO HELP</span><h1>How can we help?</h1><p>Search common questions or send our support team a message.</p><label><Search /><input v-model="query" aria-label="Search help topics" placeholder="Search orders, returns, payments..." /></label></div><div class="support-grid"><section class="support-panel"><h2>Popular questions</h2><details v-for="faq in filteredFaqs" :key="faq.q"><summary>{{ faq.q }}<ChevronDown /></summary><p>{{ faq.a }}</p></details><p v-if="!filteredFaqs.length" class="no-results">No matching help topics. Send us a support request.</p></section><form class="support-panel ticket-form" @submit.prevent="submit"><div class="panel-title"><MessageCircle /><div><h2>Contact support</h2><p>We usually reply within one business day.</p></div></div><label>What do you need help with?<select v-model="topic"><option>Order and delivery</option><option>Returns and refunds</option><option>Payments</option><option>Account access</option><option>Other</option></select></label><label>Your message<textarea v-model="message" rows="4" placeholder="Share the details that will help us resolve this."></textarea></label><button class="support-button" type="submit">Send message</button><p v-if="submitted" class="success"><CheckCircle2 /> Your support request has been saved.</p><div v-if="tickets.length" class="ticket-history"><b>Recent requests</b><p v-for="ticket in tickets.slice(0,3)" :key="ticket.id">{{ ticket.id }} · {{ ticket.topic }} <span>{{ ticket.status }}</span></p></div></form></div></main><SiteFooter /></div></template>

<style scoped>
