-top:1px solid #edf0f4;padding-top:14px;font-size:12px;color:#34445b}.ticket-history p{display:flex;justify-content:space-between;color:#6c7a8d}.ticket-history span{color:#178557}@media(max-width:760px){.support-grid{grid-template-columns:1fr}.support-intro h1{font-size:26px}}
</style>
